import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <float.h>
#include <stdint.h>
__global__ void min_dim1_kernel(const float* __restrict__ x,
                                float* __restrict__ out,
                                int B, int M, int N,
                                long long total) {
    // Wide-column sweep reduction: each thread owns a single output
    // column and the 256-thread block covers a contiguous 256-column
    // tile, so every step down the M axis gives the block a contiguous
    // 1KB footprint per row. With an odd row pitch (N floats) narrow
    // 128B warp tiles are almost never 32B-sector aligned and overfetch
    // ~25% extra DRAM traffic; the 1KB block-wide footprint makes
    // essentially every fetched sector fully consumed. Eight
    // independent accumulators keep 8 loads in flight per thread, and
    // no shared-memory reduction tree is needed.
    const int b = blockIdx.x;
    const int j = blockIdx.y * 256 + threadIdx.x;
    if (j >= N) return;
    const long long stride = (long long)N;
    const float* p = x + ((size_t)b * (size_t)M) * (size_t)stride + (size_t)j;
    const size_t step = (size_t)stride;
    float mn0 = FLT_MAX, mn1 = FLT_MAX, mn2 = FLT_MAX, mn3 = FLT_MAX;
    float mn4 = FLT_MAX, mn5 = FLT_MAX, mn6 = FLT_MAX, mn7 = FLT_MAX;
    int i = 0;
    for (; i + 7 < M; i += 8) {
        mn0 = fminf(mn0, __ldg(p));
        mn1 = fminf(mn1, __ldg(p + step));
        mn2 = fminf(mn2, __ldg(p + 2 * step));
        mn3 = fminf(mn3, __ldg(p + 3 * step));
        mn4 = fminf(mn4, __ldg(p + 4 * step));
        mn5 = fminf(mn5, __ldg(p + 5 * step));
        mn6 = fminf(mn6, __ldg(p + 6 * step));
        mn7 = fminf(mn7, __ldg(p + 7 * step));
        p += 8 * step;
    }
    for (; i < M; ++i) {
        mn0 = fminf(mn0, __ldg(p));
        p += step;
    }
    mn0 = fminf(fminf(mn0, mn1), fminf(mn2, mn3));
    mn4 = fminf(fminf(mn4, mn5), fminf(mn6, mn7));
    out[((size_t)b * (size_t)stride) + (size_t)j] = fminf(mn0, mn4);
}
torch::Tensor min_dim1_cuda(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(x.dim() == 3, "x must be 3D");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    const int B = (int)x.size(0);
    const int M = (int)x.size(1);
    const int N = (int)x.size(2);
    auto out = torch::empty({B, N}, x.options());
    const long long total = (long long)B * (long long)N;
    if (total == 0) return out;
    const dim3 block(256);
    const dim3 grid((unsigned)B, (unsigned)((N + 255) / 256));
    auto stream = at::cuda::getCurrentCUDAStream();
    min_dim1_kernel<<<grid, block, 0, stream>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        B, M, N, total
    );
    return out;
}
"""
_cpp_src = "torch::Tensor min_dim1_cuda(torch::Tensor x);"
_min_mod = load_inline(
    name="min_dim1_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["min_dim1_cuda"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)
class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        d = self.dim if self.dim >= 0 else x.dim() + self.dim
        if x.dim() == 3 and d == 1 and x.dtype == torch.float32:
            x = x.contiguous()
            if not x.is_cuda:
                x = x.cuda()
            return _min_mod.min_dim1_cuda(x)
        return torch.min(x, dim=self.dim)[0]

